pm.test("POST /api/auth/login responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta incluye un token Bearer", function () {
    const respuesta = pm.response.json();
    pm.expect(respuesta).to.have.property("accessToken").that.is.a("string");
    pm.expect(respuesta.accessToken).to.not.be.empty;
    pm.expect(respuesta).to.have.property("tokenType", "Bearer");
    pm.expect(respuesta).to.have.property("expiresIn");

    pm.collectionVariables.set("jwtToken", respuesta.accessToken);
    try { pm.environment.set("jwtToken", respuesta.accessToken); } catch (e) {}
    console.log("JWT guardado en jwtToken.");
});

pm.test("POST /api/carrito/items responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("El carrito contiene la presentación agregada", function () {
    const carrito = pm.response.json();
    const item = (carrito.items || []).find(function (elemento) {
        return elemento.formatoLibroId === 1;
    });
    pm.expect(item, "No se encontró el ítem agregado").to.not.be.undefined;
});

pm.test("Checkout con carrito vacío responde 400", function () {
    pm.response.to.have.status(400);
});

pm.test("El sistema rechaza la compra sin artículos", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.estado).to.eql(400);
    pm.expect(respuesta.mensaje)
        .to.eql("No se puede confirmar un carrito vacío.");
    pm.expect(respuesta.ruta).to.eql("/api/checkout");
});

pm.test("Checkout sin existencias suficientes responde 400", function () {
    pm.response.to.have.status(400);
});

pm.test("El sistema informa las existencias disponibles", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.estado).to.eql(400);
    pm.expect(respuesta.error).to.eql("Bad Request");
    pm.expect(respuesta.mensaje).to.include("Existencias insuficientes");
    pm.expect(respuesta.mensaje).to.match(/Disponibles:\s*\d+/);
    pm.expect(respuesta.ruta).to.eql("/api/checkout");
});
